import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as e,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"元宝学习地图","description":"腾讯元宝是消费级全能 AI 助手。本目录只写元宝。混元和 CodeBuddy 各占一行。","frontmatter":{"title":"元宝学习地图","description":"腾讯元宝是消费级全能 AI 助手。本目录只写元宝。混元和 CodeBuddy 各占一行。","domain":"product","tags":["chat"],"role":"map"},"headers":[],"relativePath":"zh/products/yuanbao/index.md","filePath":"zh/products/yuanbao/index.md","lastUpdated":1787110548000}'),d={name:"zh/products/yuanbao/index.md"};function r(o,t,p,l,i,c){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="元宝学习地图" tabindex="-1">元宝学习地图 <a class="header-anchor" href="#元宝学习地图" aria-label="Permalink to &quot;元宝学习地图&quot;">​</a></h1><blockquote><p><strong>元宝</strong>是腾讯的消费级全能 AI 助手。官方英文 title（<a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a>）： <strong>Yuanbao–Tencent&#39;s All-in-One AI Assistant</strong></p><p>同页原文：「元宝是腾讯推出的全能 AI 助手，已接入最新的混元 Hy3 模型」。</p><p>本目录只写<strong>元宝</strong>。混元模型站和 CodeBuddy 各占一行，正文在别的 issue。</p></blockquote><h2 id="写给谁-不写什么" tabindex="-1">写给谁 / 不写什么 <a class="header-anchor" href="#写给谁-不写什么" aria-label="Permalink to &quot;写给谁 / 不写什么&quot;">​</a></h2><p><strong>写给谁：</strong> 需要一个能在浏览器或桌面里聊天、搜资料、读文件、写文案的前端工程师。不需要仓库。</p><p><strong>目标：</strong> 分清元宝和同厂其它 AI 入口，按官方页面打开产品，知道电脑版比网页多了什么。</p><p><strong>非目标：</strong></p><ul><li>腾讯混元模型 / API / 开源权重（#77）</li><li>CodeBuddy 编程助手教程（#78）</li><li>微信 / QQ / 腾讯会议操作</li><li>臆造会员价、默认模型名、36 种文件后缀</li><li>模型内部机制（去 <a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a>）</li></ul><h2 id="产品全景" tabindex="-1">产品全景 <a class="header-anchor" href="#产品全景" aria-label="Permalink to &quot;产品全景&quot;">​</a></h2><p>混元站页脚把元宝和其它 AI 产品列在一起。它们<strong>不是</strong>同一个产品的几张皮。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>腾讯 AI（本目录只展开元宝）</span></span>
<span class="line"><span>├── 元宝 — 消费级全能助手</span></span>
<span class="line"><span>│   ├── 网页 yuanbao.tencent.com</span></span>
<span class="line"><span>│   ├── iOS / Android</span></span>
<span class="line"><span>│   ├── Windows / macOS 电脑版</span></span>
<span class="line"><span>│   └── 元宝派（商店写明：开启公测）</span></span>
<span class="line"><span>├── 腾讯混元 — 模型家族与研究站（#77，一行）</span></span>
<span class="line"><span>├── CodeBuddy — 云代码助手（#78，一行）</span></span>
<span class="line"><span>├── WorkBuddy — 全场景 AI 办公工作台（页脚一行）</span></span>
<span class="line"><span>├── ima — AI 知识管家（页脚一行）</span></span>
<span class="line"><span>└── Hy AI Studio — 混元站页脚的模型试玩（一行）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>入口</th><th>是什么</th><th>官方 URL</th><th>本站</th></tr></thead><tbody><tr><td><strong>元宝</strong></td><td>聊天 / 写作 / 搜索 / 文件 / 多模态助手</td><td><a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a></td><td><a href="./yuanbao.html">教程</a></td></tr><tr><td>腾讯混元</td><td>模型、研究、开源、Co-design</td><td><a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a></td><td>地图一行（#77）</td></tr><tr><td>CodeBuddy</td><td>腾讯云代码助手</td><td><a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">codebuddy.cn</a></td><td>地图一行（#78）</td></tr><tr><td>WorkBuddy</td><td>「全场景 AI 办公工作台」</td><td><a href="https://www.workbuddy.cn/" target="_blank" rel="noreferrer">workbuddy.cn</a></td><td>地图一行</td></tr><tr><td>ima</td><td>「以知识库为基础的AI知识管家」</td><td><a href="https://ima.qq.com/" target="_blank" rel="noreferrer">ima.qq.com</a></td><td>地图一行</td></tr><tr><td>Hy AI Studio</td><td>混元站 <code>/solutions</code> 页脚产品项</td><td><a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a></td><td>地图一行</td></tr><tr><td>微信 / QQ / 会议</td><td>非本站产品</td><td>—</td><td><strong>非本站</strong></td></tr></tbody></table><p>页脚来源：2026-08-19 打开 <a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a>（产品：WorkBuddy、元宝、ima）和 <a href="https://hunyuan.tencent.com/solutions" target="_blank" rel="noreferrer">hunyuan.tencent.com/solutions</a>（产品：Hy AI Studio、元宝、WorkBuddy）。两页不一致，上表取并集。</p><p><strong>容易撞名：</strong></p><ul><li><strong>元宝 ≠ 混元。</strong> 元宝是助手产品。混元是模型与研究品牌。</li><li><strong>元宝 ≠ CodeBuddy。</strong> 元宝的「AI 编程」是对话里跑 Python / C++（<a href="https://yuanbao.tencent.com/evt/dl" target="_blank" rel="noreferrer">电脑版页</a>）。仓库 / IDE 编码不在本目录写。</li><li><strong>元宝 ≠ WorkBuddy ≠ ima。</strong> 后两个只在混元页脚出现，本目录不展开。</li><li><strong><code>hunyuan.tencent.com/bot/chat</code> 不是第二个产品。</strong> 该页 canonical 指向 <code>yuanbao.tencent.com</code>。</li><li><strong>元宝派不是独立 App。</strong> App Store / Play 把它写在元宝「特色功能」里，并标明公测。</li></ul><h3 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个？ <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 网页或电脑里聊天、写作、搜索、读文件、识图、划词</span></span>
<span class="line"><span>│   └── → 元宝（本目录）</span></span>
<span class="line"><span>│       ├── 先打开网页？→ yuanbao.tencent.com</span></span>
<span class="line"><span>│       └── 要划词 / 迷你窗 / 本地唤起？→ 电脑版（evt/dl）</span></span>
<span class="line"><span>├── 在仓库或 IDE 里写代码、补全、改项目</span></span>
<span class="line"><span>│   └── → CodeBuddy（官方 codebuddy.cn；#78，这里不写教程）</span></span>
<span class="line"><span>├── 调用混元模型 / 看论文 / 下开源权重</span></span>
<span class="line"><span>│   └── → 腾讯混元（hunyuan.tencent.com；#77）</span></span>
<span class="line"><span>├── 办公任务交给 Agent 做完（报告 / 多工具）</span></span>
<span class="line"><span>│   └── → WorkBuddy（workbuddy.cn，本站不写）</span></span>
<span class="line"><span>├── 用知识库做搜-读-写</span></span>
<span class="line"><span>│   └── → ima（ima.qq.com，本站不写）</span></span>
<span class="line"><span>└── 微信 / QQ / 会议本身</span></span>
<span class="line"><span>    └── → 非本站</span></span></code></pre></div><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>读什么</th><th>目标</th></tr></thead><tbody><tr><td>1. 打开能聊</td><td><a href="./yuanbao.html">元宝教程</a> 的入口表</td><td>网页或客户端里发出第一句</td></tr><tr><td>2. 知道电脑版多什么</td><td>同页「电脑版」</td><td>划词、迷你窗、本地跑 Python / C++</td></tr><tr><td>3. 回查链接</td><td><a href="./yuanbao-cheatsheet.html">速查表</a></td><td>商店、协议、支持邮箱</td></tr><tr><td>4. 名字分清</td><td><a href="./yuanbao-glossary.html">术语表</a></td><td>不再把混元 / CodeBuddy 叫成元宝</td></tr></tbody></table><p>官方没有 How-to 文档树，本目录<strong>不设 cookbook</strong>。逐步点击以产品里的 UI 为准。</p><h2 id="功能速查-只抄官方页" tabindex="-1">功能速查（只抄官方页） <a class="header-anchor" href="#功能速查-只抄官方页" aria-label="Permalink to &quot;功能速查（只抄官方页）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>官方原文出处</th></tr></thead><tbody><tr><td>全能 AI 助手，已接入混元 Hy3</td><td><a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">首页 description</a></td></tr><tr><td>聊天、写作、搜索</td><td>首页 tagline</td></tr><tr><td>文件拖拽上传</td><td>首页</td></tr><tr><td>AI 写作 / AI 编程 / AI 识图 / AI 划词</td><td><a href="https://yuanbao.tencent.com/evt/dl" target="_blank" rel="noreferrer">电脑版页</a></td></tr><tr><td>Python、C++ 多语言运行，无需部署即时验证</td><td>电脑版页</td></tr><tr><td>36 种文件（代码、日志、技术文档）</td><td>电脑版页；<strong>未公布后缀列表</strong></td></tr><tr><td>Option+空格（mac）/ Alt+空格（window）迷你对话窗</td><td>电脑版页（原文 <code>window</code>）</td></tr><tr><td>临时对话不进历史</td><td>电脑版页</td></tr><tr><td>拍题、录音笔、元宝派公测、语音通话、生视频…</td><td><a href="https://apps.apple.com/cn/app/%E5%85%83%E5%AE%9D-%E8%85%BE%E8%AE%AF%E5%85%A8%E8%83%BDai%E5%8A%A9%E6%89%8B/id6480446430" target="_blank" rel="noreferrer">App Store</a> / <a href="https://play.google.com/store/apps/details?id=com.tencent.hunyuan.app.chat" target="_blank" rel="noreferrer">Play</a></td></tr><tr><td>内容由 AI 生成，仅供参考</td><td>首页、下载中心</td></tr></tbody></table><p>套餐与额度：2026-08-19 <strong>没有</strong>找到元宝官方价目表。App Store 标「免费」。不要把第三方「全功能无限制」写进正文。</p>`,22)])])}const m=a(d,[["render",r]]);export{g as __pageData,m as default};
